"""Shared contract for text plans generated by the frozen action Teacher."""
from __future__ import annotations
from typing import Any


class InvalidTeacherPlan(ValueError):
    """The Teacher produced no usable text."""


def plan_generation_kwargs(tokenizer: Any, vocab_size: int, max_new_tokens: int) -> dict[str, Any]:
    """Require a content token before EOS and exclude non-text action/special IDs."""
    from vlade.models.teachers.constants import ACTION_TOKEN_BEGIN_IDX

    if type(max_new_tokens) is not int or not 1 <= max_new_tokens <= 128:
        raise ValueError("Plan generation requires max_new_tokens in [1, 128]")
    eos = tokenizer.eos_token_id
    if type(eos) is not int or not 0 <= eos < min(vocab_size, ACTION_TOKEN_BEGIN_IDX + 1):
        raise ValueError("T1 tokenizer requires an EOS token in the text vocabulary")
    suppressed = set(range(ACTION_TOKEN_BEGIN_IDX + 1, vocab_size))
    special = list(getattr(tokenizer, "all_special_ids", ()))
    special.extend(getattr(tokenizer, name, None) for name in ("bos_token_id", "unk_token_id", "pad_token_id"))
    suppressed.update(token for token in special if type(token) is int and 0 <= token < vocab_size and token != eos)
    return {"max_new_tokens": max_new_tokens, "min_new_tokens": 1,
            "do_sample": False, "use_cache": True, "return_dict_in_generate": False,
            "eos_token_id": eos, "pad_token_id": eos,
            "forced_bos_token_id": None, "forced_eos_token_id": None,
            "suppress_tokens": sorted(suppressed)}


def plan_token_budget(settings: dict) -> int:
    """Zero selects action-only KD; a positive budget requires the online Teacher."""
    budget = settings.get("teacher_plan_max_new_tokens", 0)
    if type(budget) is not int or not 0 <= budget <= 128:
        raise ValueError("teacher_plan_max_new_tokens must be an integer in [0, 128]")
    if budget and settings.get("teacher_mode") != "inference":
        raise ValueError("Teacher plans require teacher_mode=inference")
    return budget


def normalize_plan(text: str) -> str:
    """Accept bounded plain text suitable for a Student prompt."""
    if not isinstance(text, str):
        raise InvalidTeacherPlan("T1 plan must be text")
    text = " ".join(text.split())
    if (len(text) > 2048 or not text.isprintable() or "<" in text or ">" in text
            or not any(char.isalpha() for char in text)):
        raise InvalidTeacherPlan("T1 emitted an invalid or empty approach plan")
    return text


def normalize_generated_plan(text: str) -> str:
    """Unwrap an optional plan tag pair from the decoded T1 response."""
    if not isinstance(text, str):
        raise InvalidTeacherPlan("T1 plan must be text")
    decoded = text
    text = text.strip()
    if text.startswith("<plan>") and text.endswith("</plan>"):
        text = text.removeprefix("<plan>").removesuffix("</plan>")
    try:
        return normalize_plan(text)
    except InvalidTeacherPlan as error:
        preview = repr(decoded[:256])
        suffix = " (truncated)" if len(decoded) > 256 else ""
        raise InvalidTeacherPlan(f"{error}; decoded T1 response={preview}{suffix}") from error


def prompt_text(plan: str, timestep: int | None) -> str:
    if type(timestep) is not int or timestep < 0:
        raise ValueError("Teacher plan requires its observation timestep")
    return f"Teacher approach plan at t={timestep}: {normalize_plan(plan)}"
